import{_ as o,o as r,c as a,a2 as l}from"./chunks/framework.vLhlLNVn.js";const u=JSON.parse('{"title":"💾 云端录像与计划任务","description":"","frontmatter":{},"headers":[],"relativePath":"media/cloud-record.md","filePath":"media/cloud-record.md"}'),t={name:"media/cloud-record.md"};function d(i,e,c,n,s,_){return r(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="💾-云端录像与计划任务" tabindex="-1">💾 云端录像与计划任务 <a class="header-anchor" href="#💾-云端录像与计划任务" aria-label="Permalink to &quot;💾 云端录像与计划任务&quot;">​</a></h1><p>MzMedia 提供了灵活的录像管理体系，同时支持<strong>设备端本地录像回放</strong>与<strong>平台云端集中录像存储</strong>。</p><hr><h2 id="_1-录像模式划分" tabindex="-1">1. 录像模式划分 <a class="header-anchor" href="#_1-录像模式划分" aria-label="Permalink to &quot;1. 录像模式划分&quot;">​</a></h2><ol><li><strong>设备前端录像 (NVR/TF 卡)</strong>： <ul><li>录像文件保存在摄像机机身 TF 卡或现场 NVR 硬盘中；</li><li>平台通过 GB28181 历史录像检索信令（<code>RecordInfo</code>）获取时间轴片段，并在用户回放时通过 SIP <code>INVITE</code> 请求点播历史流。</li></ul></li><li><strong>平台云端集中录像 (Cloud Record)</strong>： <ul><li>由 ZLMediaKit 流媒体服务器根据后台设定的计划自动对实时媒体流进行 MP4 切片（默认 5~30 分钟一个切片）；</li><li>切片信息入库至 <code>wvp_cloud_record</code> 表，切片文件可存储在本地磁盘或 MinIO / 阿里云 OSS 对象存储中。</li></ul></li></ol><hr><h2 id="_2-定时录像计划配置-wvp-record-plan" tabindex="-1">2. 定时录像计划配置 (<code>wvp_record_plan</code>) <a class="header-anchor" href="#_2-定时录像计划配置-wvp-record-plan" aria-label="Permalink to &quot;2. 定时录像计划配置 (`wvp_record_plan`)&quot;">​</a></h2><p>在前端 <strong>视频中心 -&gt; 录像计划</strong> 页面中：</p><ul><li>支持为每一个视频通道设定按周轮询的定时计划（如：仅在工作日 19:00 - 次日 07:00 录像）；</li><li>支持设置切片保留天数（如保存 30 天，超期由后台定时调度自动清理并释放磁盘空间）；</li><li>回放界面支持按天查询、时间轴绿色色块可视化拖拽与倍速播放（0.5x, 1x, 2x, 4x）。</li></ul>',9)])])}const h=o(t,[["render",d]]);export{u as __pageData,h as default};
